// Get planet description from table
function getPlanetInHouseDesc(planet, house, sign) {
  const key = planet + '_' + house + '_' + sign.slice(0,3);
  const entry = KP_PLANET_TABLE[key];
  if (!entry) return null;
  const domain = HOUSE_DOMAIN_MAP[house] || 'general';
  const [pi, ni] = DOMAIN_IDX[domain];
  return { condition: entry[0], pos: entry[pi], neg: entry[ni] };
}

